  (109, 'Perda', '6', 2023, 'Peraturan Daerah Provinsi Kalimantan Selatan Nomor 6 Tahun 2023 tentang Rencana Tata Ruang Wilayah Provinsi Kalimantan Selatan Tahun 2023-2042', 'berlaku', 'Mencabut Perda Provinsi Kalimantan Selatan No. 9 Tahun 2015', '{}', 'Prov. Kalimantan Selatan', 'Tata Ruang', 'https://dpmptsp.kalselprov.go.id/web/download/peraturan-daerah-provinsi-kalimantan-selatan-nomor-6-tahun-2023-tentang-rencana-tata-ruang-wilayah-provinsi-kalimantan-selatan-tahun-2023-2042/', 'normal', '2026-09-01 11:35:02', '2026-09-01 11:35:02'),
