INSERT INTO pasal (id, peraturan_id, nomor_pasal, nomor_ayat, teks_pasal) VALUES
  (228, 55, 'Pasal 18', 'Ayat (1)', 'Negara Kesatuan Republik Indonesia dibagi atas daerah-daerah provinsi dan daerah provinsi itu dibagi atas kabupaten dan kota, yang tiap-tiap provinsi, kabupaten, dan kota itu mempunyai pemerintahan daerah, yang diatur dengan undang-undang.'),
  (229, 55, 'Pasal 18', 'Ayat (6)', 'Pemerintahan daerah berhak menetapkan peraturan daerah dan peraturan-peraturan lain untuk melaksanakan otonomi dan tugas pembantuan.'),
  (230, 55, 'Pasal 18B', 'Ayat (2)', 'Negara mengakui dan menghormati kesatuan-kesatuan masyarakat hukum adat serta hak-hak tradisionalnya sepanjang masih hidup dan sesuai dengan prinsip Negara Kesatuan Republik Indonesia.'),
  (231, 55, 'Pasal 28H', 'Ayat (1)', 'Setiap orang berhak hidup sejahtera lahir dan batin, bertempat tinggal, dan mendapatkan lingkungan hidup yang baik dan sehat serta berhak memperoleh pelayanan kesehatan.'),
  (232, 55, 'Pasal 33', 'Ayat (3)', 'Bumi dan air dan kekayaan alam yang terkandung di dalamnya dikuasai oleh negara dan dipergunakan untuk sebesar-besar kemakmuran rakyat.'),
  (237, 57, 'Pasal 4', 'Ayat (1)', 'Jenis Pajak yang dipungut oleh Pemerintah Provinsi terdiri atas PBBKB, PKB, BBNKB, PAP, dan Pajak Alat Berat.'),
  (238, 57, 'Pasal 94', 'Ayat (1)', 'Jenis Pajak Daerah dan Retribusi Daerah, Subjek Pajak dan Wajib Pajak, Subjek Retribusi dan Wajib Retribusi, objek Pajak dan Retribusi, dasar pengenaan Pajak, tingkat penggunaan jasa Retribusi, tarif Pajak dan Retribusi, serta tata cara penghitungan Pajak dan Retribusi ditetapkan dalam 1 (satu) Perda.'),
  (239, 58, 'Pasal 1', 'Ayat (1)', 'Menetapkan Peraturan Pemerintah Pengganti Undang-Undang Nomor 2 Tahun 2022 tentang Cipta Kerja menjadi Undang-Undang.'),
  (240, 58, 'Pasal 2', 'Ayat (1)', 'Lampiran Peraturan Pemerintah Pengganti Undang-Undang Nomor 2 Tahun 2022 tentang Cipta Kerja merupakan bagian yang tidak terpisahkan dari Undang-Undang ini.'),
  (241, 58, 'Pasal 3', 'Ayat (1)', 'Undang-Undang ini mulai berlaku pada tanggal diundangkan.'),
  (242, 58, 'Pasal 6', 'Ayat (1)', 'Peningkatan ekosistem investasi dan kegiatan berusaha meliputi penerapan perizinan berusaha berbasis risiko.'),
  (243, 58, 'Pasal 12', 'Ayat (2)', 'Pemerintah Daerah wajib menerapkan sistem Perizinan Berusaha Terintegrasi Secara Elektronik (Online Single Submission / OSS) dalam pemberian perizinan berusaha di daerah.'),
  (246, 60, 'Pasal 6', 'Ayat (2)', 'Perencanaan tata ruang dilaksanakan untuk menghasilkan Rencana Tata Ruang Wilayah (RTRW) Provinsi dan Rencana Tata Ruang Wilayah Kabupaten/Kota.'),
  (247, 60, 'Pasal 58', 'Ayat (1)', 'Kesesuaian Kegiatan Pemanfaatan Ruang (KKPR) merupakan kesesuaian antara rencana lokasi kegiatan pemanfaatan ruang dengan Rencana Tata Ruang.'),
  (248, 61, 'Pasal 3', 'Ayat (1)', 'Persetujuan Lingkungan wajib dimiliki oleh setiap Usaha dan/atau Kegiatan yang memiliki Dampak Penting atau Tidak Dampak Penting terhadap lingkungan hidup.'),
  (249, 61, 'Pasal 480', 'Ayat (2)', 'Pemerintah Daerah berwenang melakukan pengawasan terhadap penaatan pemegang Persetujuan Lingkungan di daerah.'),
  (250, 62, 'Pasal 14', 'Ayat (1)', 'Parkir insidental dapat diselenggarakan di dalam Ruang Milik Jalan, dalam hal tempat parkir di luar ruang milik jalan telah melebihi kapasitas.'),
  (251, 62, 'Pasal 14', 'Ayat (2)', 'Penyelenggaraan parkir insidental sebagaimana dimaksud pada ayat (1) dilakukan dengan pertimbangan tidak mengganggu keselamatan, ketertiban dan kelancaran lalu lintas.'),
  (380, 101, 'Pasal 8', 'Ayat (1)', 'Kewenangan Pemerintah Daerah Provinsi dalam penyelenggaraan Jasa Konstruksi meliputi: a. penyelenggaraan pelatihan tenaga ahli konstruksi; b. penyelenggaraan sistem informasi Jasa Konstruksi.'),
  (381, 101, 'Pasal 14', 'Ayat (1)', 'Usaha Jasa Konstruksi mencakup jenis usaha, sifat usaha, dan klasifikasi usaha Jasa Konstruksi.'),
  (405, 109, 'Pasal 1', 'Angka 1', 'Rencana Tata Ruang Wilayah Provinsi Kalimantan Selatan yang selanjutnya disingkat RTRW Provinsi adalah rencana tata ruang yang mengatur struktur ruang dan pola ruang wilayah Provinsi Kalimantan Selatan.'),
  (406, 109, 'Pasal 3', '', 'Penataan ruang wilayah Provinsi bertujuan untuk mewujudkan Kalimantan Selatan sebagai Gerbang Logistik Kalimantan dan Pintu Gerbang Ibu Kota Nusantara.'),
  (413, 111, 'Pasal 1', 'Angka 1', 'Rencana Pembangunan Jangka Menengah Daerah Provinsi Kalimantan Selatan Tahun 2021-2026 adalah dokumen perencanaan pembangunan daerah untuk periode 5 (lima) tahun.'),
  (414, 111, 'Pasal 3', 'Ayat (1)', 'Visi Pembangunan Jangka Menengah Daerah Provinsi Kalimantan Selatan Tahun 2021-2026 adalah Kalsel Maju (Kalimantan Selatan Makmur, Sejahtera, dan Berkelanjutan) sebagai Gerbang Ibu Kota Negara.');
